INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-055', 'SW', 'P2', 'OPEN', NULL, NULL, 'close-adversarial-pass CANNOT BE SATISFIED BY A GOOD-FAITH, WELL-FORMED SURVIVED FINDING, AND NOTHING CAN FIX ONE AFTER RECORDING. Found closing batch 21''s adversarial pass (pass_id=2): close_adversarial_pass() requires every SURVIVED-verdict finding''s artefact field to resolve, via dbcore.resolve_under, to exactly one existing file under the repo (a bare path, no delimiters, no row/line references). All 9 of this pass''s SURVIVED findings fail this: the antagonist wrote richer, information-dense citations for several of them -- two files joined with ''; '' or ''and'' (e.g. ''retrieval-log/.../18ef7d575e63330c.xml; 6ab420aabe807589.zip''), a code symbol plus file (''schemas/tier_derivation.py TIER_MAP''), a table-and-row reference (''source_value_extractions rows 70 and 71 (batch21.db)''), a DB-column-and-file pairing (''evidence_sources.co1_provenance REF-01009 vs 18ef7d575e63330c.xml'') -- none of which is a bare resolvable path, though every one names something real and checkable. THE ANTAGONIST''S OWN INSTRUCTIONS (.claude/agents/antagonist.md, ''Report shape'') DO show the correct bare-path format in their worked example, so this is a genuine deviation by the reviewing agent, not solely a gate-design problem -- but the consequence is disproportionate: once record-adversarial-pass has parsed the findings block from the (tracked, immutable) reviewer transcript, NOTHING can correct a SURVIVED row''s artefact field. dispose-adversarial-finding only writes disposition/disposition_ref, and only for a finding at all (its own CLI does not gate by verdict, but nothing in db.py updates artefact for any verdict). record-adversarial-pass itself refuses a second pass for the same subject_session (''at most one adversarial pass per research batch''). So a single formatting slip by the reviewing model, on a SURVIVED (not even a SUSTAINED) finding, permanently blocks close-adversarial-pass and therefore adversarial_pass_recorded/research_batch_dod for the whole batch, with no remediation path short of a schema-level fix. THIS BATCH''S OWN INSTANCE: pass_id=2 is RECORDED but left OPEN, as a reasoned waiver (research_batch_dod has no R-rule for this specifically, but adversarial_pass_audit.py --session reports ''FAIL: 1 pass(es) recorded... none is CLOSED''). WHAT WOULD CLOSE THIS GAP: (a) a writer that can correct a SURVIVED finding''s artefact field, symmetrical to dispose-adversarial-finding for SUSTAINED ones (with its own --reason, so a correction is not silent); or (b) close_adversarial_pass accepting a semicolon/''and''-delimited list of paths, checking that at least one resolves, rather than requiring the whole string to resolve as one path; or (c) the antagonist agent''s own report-writing being hardened (a self-check before hand-back: does every SURVIVED artefact field parse as a single existing path) so this is caught before the transcript is finalised and immutable.', '2026-09-28 07:46', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:46', 'session_2026-09-28-research-batch-21-selection', NULL, NULL, NULL, NULL, NULL);

